/**
 * TypeScript types generated from the Supabase database schema.
 *
 * In a real project these would be auto-generated by:
 *   npx supabase gen types typescript --project-id YOUR_PROJECT_ID > src/types/database.ts
 *
 * This hand-written version exactly mirrors the SQL schema in
 * supabase/migrations/0001_initial_schema.sql.
 * Regenerate from the live Supabase project after applying migrations.
 *
 * DO NOT add types here that don't have corresponding DB columns.
 */

export type EntitlementType =
  | "draft_only"
  | "internal_test"
  | "publishing_beta"
  | "paid_trial"
  | "paid_active"
  | "inactive";

export type AgentState =
  | "setup_required"
  | "active_approval_required"
  | "active_autopilot"
  | "paused"
  | "blocked_integration"
  | "attention_required";

export type OperatingMode = "approval_required" | "autopilot";

export type JobStatus =
  | "queued"
  | "running"
  | "waiting_for_approval"
  | "succeeded"
  | "failed_retryable"
  | "failed_terminal"
  | "canceled"
  | "needs_reconciliation";

export type IntegrationProvider = "linkedin" | "telegram" | "polar" | "mcp";
export type IntegrationStatus = "connected" | "disconnected" | "expired" | "error";

export type PostStatus =
  | "draft"
  | "needs_review"
  | "approved"
  | "scheduled"
  | "publishing"
  | "published"
  | "failed"
  | "rejected"
  | "canceled"
  | "needs_reconciliation";

export type PlanStatus = "active" | "superseded" | "archived";
export type AuditActorType = "user" | "system" | "admin" | "telegram" | "mcp";
export type ApprovalAction = "approved" | "rejected" | "revised" | "auto_approved";
export type WebhookProcessingStatus = "pending" | "processed" | "failed" | "duplicate";

